async function chooseWatchlist(id){stopQuoteStream();watch=await api(base+'/watchlists/'+id+'/activate',{});practice=false;selected=watch.keys[0]||selected;$('price-symbol').value=selected;liveBars=[];renderWatchlistControls();renderWatch();await loadChart();ensureQuoteStream();}
