 $('desk-notice').innerHTML=`<span>${esc(message)}</span>${!practice&&!connection?.session.authenticated?'<button class="text-button" data-view="setup">Connect Kite →</button>':''}`;
 renderPriceContext();
 $('desk-depth').innerHTML=q?.bid&&q?.ask?`<div class="depth-grid"><div><span>Bid · sell reference</span><strong class="positive">${money(q.bid)}</strong><small>${q.bid_quantity!==null&&q.bid_quantity!==undefined?number(q.bid_quantity,0)+' units':'Depth unavailable'}</small></div><div><span>Ask · buy reference</span><strong class="negative">${money(q.ask)}</strong><small>${q.ask_quantity!==null&&q.ask_quantity!==undefined?number(q.ask_quantity,0)+' units':'Depth unavailable'}</small></div></div>`:blank('No executable depth','A saved close can be charted; placing an order requires fresh bid/ask liquidity.');
