function smallPlot(points,keys,colors,ylabel){if(!points.length)return blank('No recorded observations','Refresh a genuine chain to record this series.');const w=850,h=230,left=45,right=15,top=15,bottom=28,x0=Math.min(...points.map(p=>p.x)),x1=Math.max(...points.map(p=>p.x)),vals=points.flatMap(p=>keys.map(k=>p[k]).filter(v=>v!==null&&v!==undefined)),lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max(hi-lo,hi*.01,.001),x=v=>left+(v-x0)/Math.max(1,x1-x0)*(w-left-right),y=v=>top+(hi-v)/span*(h-top-bottom);if(!vals.length)return blank('No usable values','The provider did not supply valid inputs for this model.');return `<div class="chart-surface"><svg viewBox="0 0 ${w} ${h}">${[0,1,2,3].map(i=>{const v=lo+(hi-lo)*i/3;return `<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#edf1f7"/><text x="1" y="${y(v)+4}" fill="#9cabc0" font-size="10">${compact(v)}</text>`;}).join('')}${keys.map((k,i)=>`<path d="${points.filter(p=>p[k]!==null&&p[k]!==undefined).map((p,n)=>`${n?'L':'M'}${x(p.x)},${y(p[k])}`).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2"/>`).join('')}<text x="${left}" y="${h-5}" fill="#9cabc0" font-size="10">${esc(ylabel)}</text></svg></div>`;}
