function syncHypothetical(){const model=$('builder-source').value==='HYPOTHETICAL';$('hypothetical-inputs').classList.toggle('hidden',!model);$('builder-expiry').disabled=model;if(!model)return;$('hypo-spot').value=$('scenario-spot').value;const dates=legs.filter(l=>l.expiry).map(l=>l.expiry.slice(0,10)).sort();const future=days=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);if(!$('hypo-expiry').value)$('hypo-expiry').value=dates[0]||$('builder-expiry').value||future(7);if(!$('hypo-next-expiry').value)$('hypo-next-expiry').value=dates.find(d=>d>dates[0])||future(14);}
function setScenario(id,value){const el=$(id);if(el.type==='range'){el.min=Math.min(Number(el.min),value);el.max=Math.max(Number(el.max),value);el.step='any';}el.value=value;}
function openDraft(d){selectedTemplate='';renderTemplates();const b=d.basket;$('studio-manual-pnl').value=b.manual_pnl??0;$('studio-include-pnl').checked=b.manual_pnl_enabled??true;$('studio-notes').value=b.notes||'';currentDraft=d.id;legs=structuredClone(b.legs);draftSource=b.source;builderKind=b.kind;$('builder-name').value=b.name;$('scenario-spot').value=b.spot;$('scenario-base-iv').value=b.volatility_pct;$('scenario-rate').value=b.interest_rate*100;$('scenario-dividend').value=b.dividend_yield*100;$('scenario-costs').value=b.cost_estimate;for(const [id,name] of [['scenario-move','target_move_pct'],['scenario-days','days_forward'],['scenario-iv','iv_shift_pp'],['scenario-range','range_pct']])setScenario(id,b.scenario?.[name]??(name==='range_pct'?5:0));if(![...$('builder-underlying').options].some(o=>o.value===b.underlying))$('builder-underlying').add(new Option(b.underlying,b.underlying));$('builder-underlying').value=b.underlying;updateExpiries();$('builder-source').value=b.source==='HYPOTHETICAL'?'HYPOTHETICAL':'KITE';const rules=b.rules;for(const [id,v] of Object.entries({'rule-family':rules.family,'rule-fast':rules.parameters.fast,'rule-slow':rules.parameters.slow,'rule-lookback':rules.parameters.lookback,'rule-z':rules.parameters.entry_z,'rule-threshold':rules.parameters.threshold*100,'rule-stop':rules.stop_pct,'rule-target':rules.target_multiple,'rule-allocation':rules.allocation_pct}))$(id).value=v;$('rule-overnight').checked=rules.allow_overnight;if(b.kind==='RULES'){$('rule-key').value=b.legs[0].key||'';$('rule-reference').value=b.spot;$('rule-side').value=b.legs[0].side;$('rule-lots').value=b.legs[0].lots;$('rule-lot-size').value=b.legs[0].lot_size;$('rule-expiry').value=b.legs[0].expiry?.slice(0,10)||'';}if(b.source==='HYPOTHETICAL'){const dates=b.legs.filter(l=>l.expiry).map(l=>l.expiry.slice(0,10)).sort();$('hypo-expiry').value=dates[0]||'';$('hypo-next-expiry').value=dates.find(d=>d>dates[0])||'';$('hypo-lot-size').value=b.legs.find(l=>l.kind==='CE'||l.kind==='PE')?.lot_size||1;}syncHypothetical();setBuilderKind(b.kind);renderLegs();scheduleAnalysis();navigate('builder');}
function setBuilderKind(kind){builderKind=kind;$('rule-builder').classList.toggle('hidden',kind!=='RULES');$('options-builder').classList.toggle('hidden',kind==='RULES');document.querySelectorAll('[data-builder-kind]').forEach(e=>e.classList.toggle('active',e.dataset.builderKind===kind));if(kind==='RULES'){if($('rule-key').value===selected)$('rule-reference').value=$('rule-reference').value||currentQuote()?.last||'';setText('builder-next-note','Save rules, then map them to historical instruments or explicitly review a forward paper test.');}else scheduleAnalysis();}
async function backtestDialog(id){const d=id?await api(base+'/drafts/'+id):await saveDraft(),datasets=await api('/api/research/datasets');dialog('Backtest '+d.basket.name,`<form id="workspace-backtest" class="dialog-form" data-draft="${d.id}"><p class="dialog-note">Choose historical data and map each leg explicitly. Current option contracts are not silently substituted into old data. Options baskets enter on the first eligible positive reference observation; stock rules use the saved signal. This run is research, separate from holdout qualification.</p><label>Historical dataset<select id="flow-dataset" required><option value="">Choose a dataset</option>${datasets.filter(x=>x.status==='READY').map(x=>`<option value="${x.id}">${esc(x.manifest.name)} · ${esc(x.manifest.source_kind)}</option>`).join('')}</select></label><label>Virtual capital · INR<input id="flow-capital" type="number" min="100" value="${state?.account.capital||1000000}" required></label><div id="flow-mappings"></div><label><input id="flow-backtest-uncovered" type="checkbox"> Explicitly allow uncovered option risk in this isolated historical research account.</label><div class="button-row"><button type="submit" class="button primary">Check & run historical test</button></div></form>`);$('flow-dataset').addEventListener('change',()=>{const dataset=datasets.find(x=>x.id===$('flow-dataset').value);if(!dataset)return;const items=dataset.manifest.instruments,selector=(name,options,label,key)=>`<label>${esc(label)}<select name="${name}" required><option value="">Map to historical instrument</option>${options.map(i=>`<option value="${esc(i.id)}" ${i.id===key?'selected':''}>${esc(i.symbol)} · ${esc(i.kind)}${i.expiry?' · '+shortDate(i.expiry):''}</option>`).join('')}</select></label>`;$('flow-mappings').innerHTML=selector('underlying',items.filter(i=>['EQ','INDEX'].includes(i.kind)),'Signal / underlying','')+d.basket.legs.map((l,i)=>selector(String(i),items.filter(x=>x.kind===(['CE','PE'].includes(l.kind)?'OPT':l.kind)&&(!['CE','PE'].includes(l.kind)||x.option_type===l.kind)),`${l.side} ${l.kind} ${l.strike||''} · leg ${i+1}`,l.key)).join('');});}
async function forwardDialog(id){const d=id?await api(base+'/drafts/'+id):await saveDraft();dialog('Start a forward paper test',`<form id="workspace-forward" class="dialog-form" data-draft="${d.id}"><p class="dialog-note">${esc(d.basket.name)} will start paused in an isolated virtual account. Only actual current contracts may be bound. Analysis premiums do not become fills. Review contracts, calendar, model assumptions and permissions before resuming.</p><label>Virtual capital · INR<input id="flow-capital" type="number" min="100" value="${state?.account.capital||1000000}" required></label><label>Reviewer<input id="flow-reviewer" required minlength="2" maxlength="100"></label><label>Review and remaining assumptions<textarea id="flow-review-note" minlength="20" required rows="3" placeholder="Record your contract, calendar, margin, execution and data review."></textarea></label><label><input id="flow-rights" type="checkbox" required> I have confirmed permitted local use of this market data.</label><label><input id="flow-assumptions" type="checkbox" required> I reviewed current contracts, dated exchange calendar, conservative margin, partial-leg execution and model limitations.</label><label><input id="flow-uncovered" type="checkbox"> Explicitly allow uncovered option risk in this virtual research account.</label><div class="button-row"><button type="submit" class="button primary">Create paused paper test</button></div></form>`);}
function manualLeg(){dialog('Add a custom analysis leg',`<form id="custom-leg-form" class="dialog-form"><p class="dialog-note">Custom prices are manual assumptions. Bind a genuine current contract before forward execution; research data mapping is explicit.</p><div class="form-grid"><label>Side<select name="side"><option>BUY</option><option>SELL</option></select></label><label>Kind<select name="kind"><option>CE</option><option>PE</option><option>EQ</option><option>FUT</option></select></label><label>Strike<input name="strike" type="number" min="0" step="0.05" required value="${Number($('scenario-spot').value)||''}"></label><label>Expiry<input name="expiry" type="date" required value="${esc($('builder-expiry').value)}"></label><label>Lots / units<input name="lots" type="number" min="1" value="1" required></label><label>Lot size<input name="lot_size" type="number" min="1" value="${chainData?.contracts[0]?.lot_size||1}" required></label><label>Entry price<input name="premium" type="number" min="0" step="0.01" required></label><label>IV %<input name="iv_pct" type="number" min="0.1" value="${Number($('scenario-base-iv').value)}" required></label><label>Current contract key · optional<input name="key" placeholder="NFO:CONTRACT"></label></div><button class="button primary" type="submit">Add analysis leg</button></form>`);}
