$('compare-drafts').addEventListener('click',async()=>{try{if(comparedDrafts.size<2||comparedDrafts.size>6)throw new Error('Select between two and six drafts using their Compare checkboxes.');const rows=await Promise.all([...comparedDrafts].map(async id=>{const d=await api(base+'/drafts/'+id),a=await api(base+'/analyze',{basket:d.basket});return {d,a};}));dialog('Compare saved strategies',`<p class="dialog-note">Each result uses that draft’s own saved underlying, spot, entry premiums, IV and fixed cost estimate. Different input bases are not ranked or presented as comparable trading performance.</p><div class="table-scroll"><table><thead><tr><th>Strategy / basis</th><th>Max profit</th><th>Max loss</th><th>Model POP</th><th>Net debit / credit</th></tr></thead><tbody>${rows.map(({d,a})=>`<tr><td>${esc(d.basket.name)}<small>${esc(d.basket.underlying)} @ ${number(d.basket.spot)}</small></td><td>${a.unlimited_profit?'Unlimited':a.max_profit===null?'Not inferred':money(a.max_profit)}</td><td>${a.unlimited_loss?'Unlimited':a.max_loss===null?'Path dependent':money(a.max_loss)}</td><td>${a.model_pop_pct===null?'—':number(a.model_pop_pct,1)+'%'}</td><td>${money(a.net_debit)}</td></tr>`).join('')}</tbody></table></div>`);}catch(e){toast(e.message,true);}});
