 const template=e.target.closest('[data-template]');if(template)await applyTemplate(template.dataset.template);
 const toggle=e.target.closest('[data-basket-side]');if(toggle){const index=Number(toggle.dataset.basketSide),l=legs[index],side=l.side==='BUY'?'SELL':'BUY',q=chainData?.contracts.find(p=>p.key===l.key);if(q)legs[index]={...legFromContract(q,side,l.lots),enabled:l.enabled,hedge:l.hedge};else{l.side=side;l.price_source='MANUAL';}renderLegs();markDirty();scheduleAnalysis();}
