 const addChain=e.target.closest('[data-chain-add]');if(addChain){const c=chainData.contracts.find(p=>p.key===addChain.dataset.chainAdd),side=addChain.dataset.chainSide;if(legs.length>=20)throw new Error('A strategy can contain at most 20 legs.');const existing=legs.find(l=>l.key===c.key&&l.side===side);const lots=Number($('studio-chain-lots').value);if(!Number.isInteger(lots)||lots<1||lots+(existing?.lots||0)>1000)throw new Error('Enter supported whole lots before adding the leg.');if(existing)existing.lots+=lots;else legs.push(legFromContract(c,side,lots));draftSource='KITE';$('scenario-spot').value=chainData.spot;renderLegs();builderTab('build');scheduleAnalysis();}
