document.addEventListener('submit',async e=>{const form=e.target;if(!['new-watchlist-form','rename-watchlist-form','custom-leg-form','workspace-backtest','workspace-forward','workspace-screener'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;
 try{if(form.id==='new-watchlist-form'){watch=await api(base+'/watchlists',{name:new FormData(form).get('name'),keys:[]});await chooseWatchlist(watch.id);}
  if(form.id==='rename-watchlist-form'){watch=await saveDisplayedWatchlist({name:new FormData(form).get('name'),keys:watch.keys});renderWatchlistControls();}
  if(form.id==='custom-leg-form'){const d=new FormData(form),kind=d.get('kind');if(legs.length>=20)throw new Error('At most 20 legs per strategy.');legs.push({key:d.get('key')?.trim().toUpperCase()||null,kind,side:d.get('side'),strike:['CE','PE'].includes(kind)?Number(d.get('strike')):0,expiry:['CE','PE','FUT'].includes(kind)?d.get('expiry')+'T15:30:00+05:30':null,lots:Number(d.get('lots')),lot_size:Number(d.get('lot_size')),premium:Number(d.get('premium')),iv_pct:['CE','PE'].includes(kind)?Number(d.get('iv_pct')):null,price_source:'MANUAL'});draftSource='MANUAL';renderLegs();markDirty();scheduleAnalysis();}
  if(form.id==='workspace-backtest'){const mapping={};form.querySelectorAll('#flow-mappings select').forEach(s=>mapping[s.name]=s.value);const result=await api(base+'/backtest',{draft_id:form.dataset.draft,dataset_id:$('flow-dataset').value,mapping,allow_uncovered_options:$('flow-backtest-uncovered').checked,capital:Number($('flow-capital').value)});toast(result.status==='FAILED'?result.error:'Historical test queued.',result.status==='FAILED');navigate('saved');switchSaved('backtests');await refreshSaved();}
  if(form.id==='workspace-forward'){await api(base+'/paper-basket',{draft_id:form.dataset.draft,capital:Number($('flow-capital').value),reviewer:$('flow-reviewer').value,review_note:$('flow-review-note').value,data_rights_confirmed:$('flow-rights').checked,assumptions_reviewed:$('flow-assumptions').checked,allow_uncovered_options:$('flow-uncovered').checked});toast('Paused paper test created. Load history and review readiness before resuming.');navigate('saved');switchSaved('forward');await refreshSaved();}
  if(form.id==='workspace-screener'){const data=new FormData(form),model=$('builder-source').value==='HYPOTHETICAL',expiry=model?$('hypo-expiry').value:$('builder-expiry').value,expiries=metadata?.underlyings.find(i=>i.name===$('builder-underlying').value)?.expiries||[],next=model?$('hypo-next-expiry').value:expiries.find(e=>e>expiry);if(!expiry)throw new Error('Choose an expiry first.');const result=await api(base+'/screener',{template:{template_id:'long_call',source:$('builder-source').value,underlying:$('builder-underlying').value,spot:Number(data.get('spot')),strike_step:model?Number($('hypo-strike-step').value):$('builder-underlying').value==='BANKNIFTY'?100:Number(data.get('spot'))>10000?50:Math.max(1,Math.round(Number(data.get('spot'))*.005)),expiry:expiry+'T15:30:00+05:30',next_expiry:next?next+'T15:30:00+05:30':null,lot_size:model?Number($('hypo-lot-size').value):chainData?.contracts[0]?.lot_size||1,volatility_pct:Number($('scenario-base-iv').value)},category:data.get('category'),target_move_pct:Number(data.get('move')),days_forward:Number(data.get('days')),iv_shift_pp:Number(data.get('iv')),max_loss:Number(data.get('loss')),cost_estimate:Number($('scenario-costs').value)});lastScreen={spot:Number(data.get('spot')),move:Number(data.get('move')),days:Number(data.get('days')),iv:Number(data.get('iv'))};$('screener-results').innerHTML=`<p class="muted">${result.results.length} matching scenarios · ${result.unavailable.length} unavailable due to missing contracts/expiries. ${esc(result.ranking)}</p><div class="table-scroll"><table><thead><tr><th>Strategy</th><th>Scenario P&L</th><th>Max loss</th><th>Model POP</th><th></th></tr></thead><tbody>${result.results.map(v=>`<tr><td>${esc(v.name)}<small>${esc(v.source)}</small></td><td class="${signClass(v.target_pnl)}">${money(v.target_pnl)}</td><td>${v.unlimited_loss?'Unlimited':v.max_loss===null?'Path dependent':money(v.max_loss)}</td><td>${v.model_pop_pct===null?'—':number(v.model_pop_pct,1)+'%'}</td><td><button type="button" class="text-button" data-load-screened="${esc(v.template_id)}">Build →</button></td></tr>`).join('')}</tbody></table></div>`;return;}
  $('workspace-dialog').close();
 }catch(error){toast(error.message,true);}finally{if(button)button.disabled=false;}});
